* { box-sizing: border-box; }
:root { color-scheme: light; font-family: system-ui, sans-serif; color: #193b37; background: #d7e8d5; }
body { min-height: 100vh; margin: 0; padding: 24px 16px; display: grid; place-items: center; background: radial-gradient(ellipse at top, #f2e6c8 0, #d7e8d5 55%, #bdd6c1 100%); }
.game-card { width: min(100%, 650px); padding: clamp(20px, 5vw, 36px); border: 4px solid #193b37; border-radius: 12px; background: #fffaf0; box-shadow: 8px 8px 0 #193b37; }
header { text-align: center; }
.eyebrow { margin: 0 0 8px; color: #a34b3f; font-weight: 750; letter-spacing: .08em; text-transform: uppercase; font-size: .88rem; }
h1 { margin: 0; font-size: clamp(1.65rem, 7vw, 2.6rem); line-height: 1.1; }
h1 span { color: #a34b3f; }
.intro { margin: 10px 0 24px; color: #41645b; font-size: 1.05rem; }
.board-wrap { padding: 12px; border: 3px solid #193b37; border-radius: 8px; background: #dcebd7; }
.board { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 4px; }
.square-cell { position: relative; display: flex; min-width: 0; aspect-ratio: 1; align-items: flex-start; justify-content: space-between; padding: 5px; overflow: hidden; border: 2px solid #41645b; border-radius: 4px; background: #fffaf0; font-size: clamp(.75rem, 3.4vw, 1rem); font-weight: 750; }
.square-cell:nth-child(even) { background: #f2e6c8; }
.square-cell.start, .square-cell.finish { background: #e8aa64; }
.cell-icon { align-self: flex-end; font-size: clamp(.8rem, 4vw, 1.2rem); line-height: 1; }
.token { position: absolute; right: 4px; bottom: 3px; display: grid; width: 24px; height: 24px; place-items: center; border: 2px solid #fffaf0; border-radius: 3px; background: #a34b3f; color: #fffaf0; font-size: 1rem; box-shadow: 0 1px 3px #193b37; }
.legend { display: flex; justify-content: center; flex-wrap: wrap; gap: 18px; margin-top: 12px; font-size: .95rem; font-weight: 650; }
.legend span { display: inline-flex; align-items: center; gap: 7px; }
.legend-mark { width: 14px; height: 14px; display: inline-block; border: 2px solid #193b37; border-radius: 3px; }
.ladder-mark { background: #e8aa64; }.snake-mark { background: #a34b3f; }.player-mark { background: #41645b; }
.controls { display: flex; align-items: stretch; justify-content: space-between; gap: 12px; margin-top: 20px; }
.status-card { flex: 1; display: grid; grid-template-columns: auto 1fr; align-items: center; column-gap: 12px; padding: 10px 14px; border: 2px solid #41645b; border-radius: 6px; background: #fff; }
.status-label { grid-column: 1; font-weight: 650; }.status-card strong { grid-column: 2; grid-row: 1 / span 2; font-size: 2rem; text-align: right; }.die-result { color: #41645b; font-size: .95rem; }
button { min-width: 140px; padding: 12px 18px; border: 3px solid #193b37; border-radius: 6px; background: #a34b3f; color: #fffaf0; font: inherit; font-size: 1.15rem; font-weight: 800; cursor: pointer; box-shadow: 0 4px 0 #193b37; transition: transform .12s ease, background .12s ease, box-shadow .12s ease; }
button:hover { background: #873b33; } button:active { transform: translateY(3px); box-shadow: 0 1px 0 #193b37; }
button:focus-visible { outline: 4px solid #e8aa64; outline-offset: 4px; } button:disabled { cursor: default; opacity: .7; }
.message { min-height: 1.5em; margin: 16px 0 0; color: #a34b3f; text-align: center; font-size: 1.08rem; font-weight: 800; }
.hint { margin: 8px 0 0; color: #41645b; text-align: center; font-size: .95rem; }
@media (max-width: 420px) { body { padding: 14px 10px; }.game-card { padding: 18px 12px; box-shadow: 5px 5px 0 #193b37; }.board-wrap { padding: 7px; }.board { gap: 3px; }.square-cell { padding: 3px; }.controls { flex-direction: column; }button { width: 100%; }.legend { gap: 12px; } }

const board = document.querySelector('#board');
const squareDisplay = document.querySelector('#square');
const dieResult = document.querySelector('#die-result');
const message = document.querySelector('#message');
const rollButton = document.querySelector('#roll-button');

const ladders = new Map([[3, 11], [8, 17], [20, 29]]);
const snakes = new Map([[14, 6], [24, 16], [28, 19]]);
let position = 1;

for (let square = 30; square >= 1; square--) {
  const cell = document.createElement('div');
  cell.className = 'square-cell';
  cell.id = `cell-${square}`;
  cell.setAttribute('role', 'gridcell');
  cell.setAttribute('aria-label', `Square ${square}`);
  if (square === 1) cell.classList.add('start');
  if (square === 30) cell.classList.add('finish');

  const number = document.createElement('span');
  number.textContent = square;
  cell.append(number);

  const mark = ladders.has(square) ? `↗ ${ladders.get(square)}` : snakes.has(square) ? `↘ ${snakes.get(square)}` : '';
  if (mark) {
    const icon = document.createElement('span');
    icon.className = 'cell-icon';
    icon.setAttribute('aria-hidden', 'true');
    icon.textContent = mark;
    cell.append(icon);
    cell.setAttribute('aria-label', `Square ${square}, ${ladders.has(square) ? 'ladder to' : 'snake to'} ${ladders.get(square) || snakes.get(square)}`);
  }
  board.append(cell);
}

function placeToken() {
  document.querySelectorAll('.token').forEach(token => token.remove());
  const token = document.createElement('span');
  token.className = 'token';
  token.textContent = '●';
  token.setAttribute('aria-label', 'Your token');
  document.querySelector(`#cell-${position}`).append(token);
}

placeToken();
rollButton.addEventListener('click', () => {
  if (position === 30) return;
  const roll = Math.floor(Math.random() * 6) + 1;
  const previous = position;
  position = Math.min(30, position + roll);
  let note = `You rolled ${roll} and moved to ${position}.`;
  if (ladders.has(position)) {
    position = ladders.get(position);
    note += ` Ladder! Climb to ${position}.`;
  } else if (snakes.has(position)) {
    position = snakes.get(position);
    note += ` Snake! Slide to ${position}.`;
  }
  squareDisplay.textContent = position;
  dieResult.textContent = `Rolled ${roll}`;
  message.textContent = position === 30 ? 'You made it to square 30. You win!' : note;
  placeToken();
  if (position === 30) {
    rollButton.disabled = true;
    rollButton.textContent = 'You won!';
  }
});
